      "code": "import impl


def test_exact_equality_boundary_with_slack_admits_and_one_step_beyond_rejects():
    capacity = 1.0
    refill_per_second = 0.0

    # cost exactly equals tokens + 1e-9 -> must be admitted (True)
    boundary_cost = 1.0 + 1e-9
    result_at_boundary = impl.simulate(capacity, refill_per_second, [(0.0, boundary_cost)])
    assert result_at_boundary == [True], (
        f"cost={boundary_cost} should satisfy tokens+1e-9 >= cost exactly and be admitted"
    )

    # cost exceeds tokens + 1e-9 by another 1e-9 -> must be rejected (False)
    beyond_cost = 1.0 + 2e-9
    result_beyond = impl.simulate(capacity, refill_per_second, [(0.0, beyond_cost)])
    assert result_beyond == [False], (
        f"cost={beyond_cost} should violate tokens+1e-9 >= cost and be rejected"
    )
